-- Bootstrap the already-published 1.4.1 facts once so upgrading preserves runtime results.
-- Future rule content uses the explicit CSV importer. Algorithms and review permissions stay Java.
CREATE TABLE gadget_rule_sets (
    game_version_id UUID PRIMARY KEY REFERENCES game_versions(id),
    passive_ruleset VARCHAR(120) NOT NULL,
    scenario_ruleset VARCHAR(120) NOT NULL
);
CREATE TABLE passive_gadget_rules (
    game_version_id UUID NOT NULL REFERENCES gadget_rule_sets(game_version_id),
    gadget_id UUID NOT NULL REFERENCES gadgets(id),
    effect_id VARCHAR(80) NOT NULL CHECK (effect_id ~ '^[a-z0-9][a-z0-9-]*$'),
    position INTEGER NOT NULL CHECK (position >= 0),
    kind VARCHAR(20) NOT NULL CHECK (kind IN ('PASSIVE','CONDITIONAL','NON_STAT','UNSUPPORTED')),
    subject VARCHAR(20) NOT NULL CHECK (subject IN ('ANY','MACHINE','RACER')),
    required_racing_type VARCHAR(20) CHECK (required_racing_type IN ('SPEED','ACCELERATION','HANDLING','POWER','BOOST')),
    matching_speed NUMERIC NOT NULL, matching_acceleration NUMERIC NOT NULL,
    matching_handling NUMERIC NOT NULL, matching_power NUMERIC NOT NULL, matching_boost NUMERIC NOT NULL,
    nonmatching_speed NUMERIC NOT NULL, nonmatching_acceleration NUMERIC NOT NULL,
    nonmatching_handling NUMERIC NOT NULL, nonmatching_power NUMERIC NOT NULL, nonmatching_boost NUMERIC NOT NULL,
    label VARCHAR(255) NOT NULL, explanation TEXT NOT NULL, stacking_group VARCHAR(80),
    scenario_stat_potential BOOLEAN,
    PRIMARY KEY (game_version_id,gadget_id,effect_id),
    UNIQUE (game_version_id,gadget_id,position),
    CHECK ((subject = 'ANY') = (required_racing_type IS NULL)),
    CHECK ((kind = 'CONDITIONAL') = (scenario_stat_potential IS NOT NULL))
);
CREATE TABLE scenario_gadget_rules (
    game_version_id UUID NOT NULL,
    gadget_id UUID NOT NULL,
    effect_id VARCHAR(80) NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    condition VARCHAR(30) NOT NULL CHECK (condition IN ('LAP_ONE','LAP_THREE','WATER','FLIGHT','TRANSFORMED','HAS_RINGS','LANDING_BOOST','FINISH_ZONE')),
    speed NUMERIC, acceleration NUMERIC, handling NUMERIC, power NUMERIC, boost NUMERIC,
    label VARCHAR(255) NOT NULL, explanation TEXT NOT NULL,
    PRIMARY KEY (game_version_id,gadget_id,effect_id),
    UNIQUE (game_version_id,position),
    FOREIGN KEY (game_version_id,gadget_id,effect_id) REFERENCES passive_gadget_rules(game_version_id,gadget_id,effect_id),
    CHECK (num_nonnulls(speed,acceleration,handling,power,boost) IN (0,5))
);
CREATE TABLE passive_rule_sources (
    game_version_id UUID NOT NULL,
    gadget_id UUID NOT NULL,
    effect_id VARCHAR(80) NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    url VARCHAR(2048) NOT NULL,
    PRIMARY KEY (game_version_id,gadget_id,effect_id,position),
    FOREIGN KEY (game_version_id,gadget_id,effect_id) REFERENCES passive_gadget_rules(game_version_id,gadget_id,effect_id)
);
CREATE TABLE scenario_rule_sources (
    game_version_id UUID NOT NULL,
    gadget_id UUID NOT NULL,
    effect_id VARCHAR(80) NOT NULL,
    position INTEGER NOT NULL CHECK (position >= 0),
    url VARCHAR(2048) NOT NULL,
    PRIMARY KEY (game_version_id,gadget_id,effect_id,position),
    FOREIGN KEY (game_version_id,gadget_id,effect_id) REFERENCES scenario_gadget_rules(game_version_id,gadget_id,effect_id)
);

